sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

	let media_array = request.body.data;

	if(JSON.stringify(media_array) == "{}") {
        response.setStatus(400);
        return "Não foi recebida nenhuma media.";
    }

	if(media_array.length == 0) {
        response.setStatus(400);
        return "Não foi recebida nenhuma media.";
    }

	try {
		var inputs = {};
		inputs['media_array'] = media_array; // Array.Object 

		// Start Asynchronously: Uncomment to run in background. Code snippet will not have access to outputs.
		// sn_fd.FlowAPI.getRunner().subflow('x_1974925_nowflix.media_inbound').inBackground().withInputs(inputs).run();

		// Execute Synchronously: Run in foreground. Code snippet has access to outputs.
		var result = sn_fd.FlowAPI.getRunner().subflow('x_1974925_nowflix.media_inbound').inForeground().withInputs(inputs).run();
		var outputs = result.getOutputs();

		// Get Outputs:
		// Note: outputs can only be retrieved when executing synchronously.
		// var result = outputs['result']; // True/False
		// var message = outputs['message']; // String
		// var processed_medias = outputs['processed_medias']; // Array.Object

		return outputs;

	} catch (ex) {
		var message = ex.getMessage();
		gs.error(message);
	}


})(request, response);
